// Puts the way of the browser for the text of images (ADR-24) into internal/web/assets/app/tesseract/: Tesseract.js as
// it ships (its module and its worker), the core for browsers with SIMD and the LSTM engine only, the language data deu
// and eng (best_int, gzipped), the small reader of UnderDoc (src/ocr.mjs) and LICENSES.txt. Everything is served by
// UnderDoc itself; nothing comes from a third party, though Tesseract.js would fetch from a CDN by default: ocr.mjs names
// every path. The output depends only on the sources and the lockfile (scripts/build-js.sh).
//
//   node build.mjs --out <dir>
import { readFileSync, writeFileSync, rmSync, mkdirSync, cpSync } from 'node:fs';
import { join, dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const at = process.argv.indexOf('--out');
const out = at > 0 ? resolve(process.argv[at + 1]) : join(here, '../../internal/web/assets/app/tesseract');
const lock = JSON.parse(readFileSync(join(here, 'package-lock.json'), 'utf8'));
const allowed = new Set(['Apache-2.0', 'MIT']);
const shipped = ['tesseract.js', 'tesseract.js-core', '@tesseract.js-data/deu', '@tesseract.js-data/eng'];
const versions = {};
for (const name of shipped) {
  const locked = lock.packages[`node_modules/${name}`];
  if (!locked) throw new Error(`${name} is not in the lockfile`);
  if (!allowed.has(locked.license)) throw new Error(`${name} has the licence ${locked.license}, which is not allowed`);
  const installed = JSON.parse(readFileSync(join(here, 'node_modules', name, 'package.json'), 'utf8'));
  if (installed.version !== locked.version) throw new Error(`${name} ${installed.version} is installed, the lockfile names ${locked.version}`);
  versions[name] = locked.version;
}
const mod = (name) => join(here, 'node_modules', name);

rmSync(out, { recursive: true, force: true });
mkdirSync(join(out, 'lang'), { recursive: true });
// The source maps stay behind: the comments that name them would only ask for files that are not there.
const noMap = (file) => readFileSync(file, 'utf8').replace(/\n\/\/# sourceMappingURL=\S+\s*$/, '\n');
writeFileSync(join(out, 'tesseract.esm.min.js'), noMap(join(mod('tesseract.js'), 'dist/tesseract.esm.min.js')));
writeFileSync(join(out, 'worker.min.js'), noMap(join(mod('tesseract.js'), 'dist/worker.min.js')));
// The core sits next to the worker: it finds its .wasm next to the script that loaded it.
for (const file of ['tesseract-core-simd-lstm.js', 'tesseract-core-simd-lstm.wasm']) cpSync(join(mod('tesseract.js-core'), file), join(out, file));
for (const lang of ['deu', 'eng']) {
  cpSync(join(mod(`@tesseract.js-data/${lang}`), `4.0.0_best_int/${lang}.traineddata.gz`), join(out, 'lang', `${lang}.traineddata.gz`));
}
cpSync(join(here, 'src/ocr.mjs'), join(out, 'ocr.mjs'));

const notices = [
  ['tesseract.js', join(mod('tesseract.js'), 'LICENSE.md')],
  ['tesseract.js-core (Tesseract, Leptonica and the libraries it is built from)', join(mod('tesseract.js-core'), 'LICENSE')],
];
writeFileSync(
  join(out, 'LICENSES.txt'),
  `The text of images in the browser of UnderDoc ships tesseract.js ${versions['tesseract.js']} and tesseract.js-core ` +
    `${versions['tesseract.js-core']} (Apache-2.0), and the language data deu and eng of @tesseract.js-data ` +
    `${versions['@tesseract.js-data/deu']} (tessdata_best int, Apache-2.0 upstream, packaged under MIT).\n` +
    'Their licences follow. Generated by web/tesseract/build.mjs from the lockfile; do not edit.\n\n' +
    notices.map(([name, file]) => `${name}\n${'-'.repeat(60)}\n${readFileSync(file, 'utf8').replace(/\r\n/g, '\n').trim()}\n`).join('\n'),
);
console.log(`tesseract.js ${versions['tesseract.js']} with the core ${versions['tesseract.js-core']} and the language data deu and eng`);
